(function($) {
    "use strict";
    $.fn.maskMoney = function(options) {
        options = $.extend({
            prefix: "",
            suffix: "",
            affixesStay: true,
            thousands: ".",
            decimal: ",",
            precision: 2,
            allowZero: false,
            allowNegative: false,
            allowEmpty: false,
            bringCaretToFront: false
        }, options);

        return this.each(function() {
            var $this = $(this);
            var onFocus = function() {
                var input = $this.get(0);
                var val = $this.val();
                $this.val(removeMask(val));
                if (options.bringCaretToFront) {
                    setCaretPosition(input, 0);
                }
            };

            var onBlur = function() {
                var val = $this.val();
                if (options.allowEmpty && val === "") {
                    return;
                }
                $this.val(maskValue(val));
                if (options.affixesStay) {
                    $this.val(options.prefix + $this.val() + options.suffix);
                }
            };

            var onKeyDown = function(e) {
                var key = e.which;
                var val = $this.val();

                if (key === 8 || key === 46) { // Backspace or Delete
                    if (val.length === 1 && val !== "0" && !options.allowEmpty) {
                        $this.val("0" + options.decimal + new Array(options.precision + 1).join("0"));
                        e.preventDefault();
                    } else if (val.length === 1 && val === "0" && options.allowEmpty) {
                        $this.val("");
                        e.preventDefault();
                    }
                } else if (key === 13) { // Enter
                    $this.trigger("blur");
                    e.preventDefault();
                } else if (key === 37 || key === 39) { // Left or Right arrow
                    return;
                } else if (key === 38 || key === 40) { // Up or Down arrow
                    e.preventDefault();
                } else if (key === 9) { // Tab
                    return;
                } else if (key === 109 || key === 189) { // Minus
                    if (options.allowNegative) {
                        var isNegative = val.indexOf("-") > -1;
                        $this.val(isNegative ? val.replace("-", "") : "-" + val);
                    }
                }
            };

            var onKeyPress = function(e) {
                var key = e.which;
                var val = $this.val();
                var selectionStart = $this.get(0).selectionStart;
                var selectionEnd = $this.get(0).selectionEnd;

                if (key < 48 || key > 57) { // Only allow numbers
                    if (key === options.decimal.charCodeAt(0) || key === options.thousands.charCodeAt(0)) {
                        return; // Allow decimal and thousands separator
                    }
                    if (key === 45 && options.allowNegative) { // Minus sign
                        return;
                    }
                    e.preventDefault();
                    return;
                }

                var oldValue = val;
                var start = selectionStart;
                var end = selectionEnd;
                var digit = String.fromCharCode(key);

                if (start !== end) {
                    val = val.substring(0, start) + val.substring(end, val.length);
                }

                if (options.bringCaretToFront && selectionStart !== 0) {
                    selectionStart = $this.get(0).selectionStart;
                    selectionEnd = $this.get(0).selectionEnd;
                    if (selectionStart !== selectionEnd && selectionStart === 0) {
                        val = oldValue.replace($this.get(0).value.substring(selectionStart, selectionEnd), '');
                    }
                }

                var caretPos = start;
                var isNegative = val.indexOf("-") > -1;
                val = removeMask(val);

                if (options.allowNegative && isNegative) {
                    val = "-" + val;
                }

                val = val.substring(0, caretPos) + digit + val.substring(caretPos, val.length);
                $this.val(maskValue(val));

                if (options.bringCaretToFront) {
                    setCaretPosition($this.get(0), Math.min(selectionStart + 1, $this.val().length));
                }
                e.preventDefault();
            };

            var removeMask = function(val) {
                if (val === null || val === undefined) {
                    return "";
                }
                var unmasked = val.replace(new RegExp("\\" + options.thousands, "g"), "");
                unmasked = unmasked.replace(new RegExp("\\" + options.decimal, "g"), "");
                if (options.prefix) {
                    unmasked = unmasked.replace(options.prefix, "");
                }
                if (options.suffix) {
                    unmasked = unmasked.replace(options.suffix, "");
                }
                if (options.allowNegative) {
                    unmasked = unmasked.replace("-", "");
                }
                return unmasked;
            };

            var maskValue = function(val) {
                val = val === "" ? "0" : val;
                if (options.allowNegative && val.indexOf("-") > -1) {
                    val = val.replace("-", "");
                    var masked = maskValue(val);
                    return "-" + masked;
                }

                var parts = val.split(options.decimal);
                var integer = parts[0];
                var decimal = parts.length > 1 ? options.decimal + parts[1] : "";
                var regex = /(\d+)(\d{3})/;
                while (regex.test(integer)) {
                    integer = integer.replace(regex, "$1" + options.thousands + "$2");
                }

                var precision = options.precision;
                if (decimal !== "") {
                    decimal = decimal.substring(0, precision + 1);
                    while (decimal.length <= precision) {
                        decimal += "0";
                    }
                } else if (precision > 0) {
                    decimal = options.decimal + new Array(precision + 1).join("0");
                }
                return integer + decimal;
            };

            var setCaretPosition = function(input, pos) {
                if (input.setSelectionRange) {
                    input.focus();
                    input.setSelectionRange(pos, pos);
                } else if (input.createTextRange) {
                    var range = input.createTextRange();
                    range.collapse(true);
                    range.moveEnd('character', pos);
                    range.moveStart('character', pos);
                    range.select();
                }
            };

            $this.on("focus", onFocus);
            $this.on("blur", onBlur);
            $this.on("keydown", onKeyDown);
            $this.on("keypress", onKeyPress);
            $this.val(maskValue($this.val()));
        });
    };

    $.fn.maskMoney.defaults = {
        prefix: "",
        suffix: "",
        affixesStay: true,
        thousands: ".",
        decimal: ",",
        precision: 2,
        allowZero: false,
        allowNegative: false,
        allowEmpty: false,
        bringCaretToFront: false
    };
})(jQuery);
